function TaskCard({ task }) {
  const priorityColors = {
    critical: 'bg-red-600 text-white',
    high: 'bg-orange-600 text-white',
    medium: 'bg-blue-600 text-white',
    low: 'bg-green-600 text-white',
  };
  const colorClass = priorityColors[task.priority] || 'bg-gray-600 text-white';

  return (
    <Card className="p-4 rounded-lg hover:shadow-md transition-shadow">
      <CardHeader>
        <CardTitle className="text-sm font-medium">{task.title}</CardTitle>
        <div className="flex items-center space-x-2 mt-2">
          {task.assignees.map((a, i) => (
            <AIKitAvatar key={i} name={a.name} status="idle" />
          ))}
        </div>
      </CardHeader>
      <CardContent className="mt-2">
        <div className="flex items-center space-x-4">
          <Badge className={colorClass}>{task.priority}</Badge>
          <span className="text-xs text-slate-500">
            Due: {task.createdAt}
          </span>
        </div>
      </CardContent>
    </Card>
  );
}

function BoardColumn({ title, items }) {
  return (
    <div className="flex-1 bg-white rounded-lg shadow-sm p-4">
      <h2 className="text-lg font-semibold mb-4">
        {title} ({items.length})
      </h2>
      <div className="space-y-4">
        {items.map(task => (
          <TaskCard key={task.id} task={task} />
        ))}
      </div>
    </div>
  );
}

function KanbanBoard({ data }) {
  const columns = [
    { key: 'todo', title: 'To Do', items: data.todo.items },
    { key: 'inProgress', title: 'In Progress', items: data.inProgress.items },
    { key: 'completed', title: 'Done', items: data.completed.items },
  ];

  return (
    <div className="p-8 flex gap-6">
      {columns.map(col => (
        <BoardColumn key={col.key} title={col.title} items={col.items} />
      ))}
    </div>
  );
}

