    { id: 2, role: 'user', name: 'You', timestamp: '4 min ago', text: 'I need to know my account balance.' },
    { id: 3, role: 'assistant', name: 'ChatBot', timestamp: '3 min ago', text: 'Sure, let me check that for you.' },
    { id: 4, role: 'assistant', name: 'ChatBot', timestamp: '2 min ago', text: 'Your balance is $1,234.56.' },
  ];

  /* ---------- State ---------- */
  const [messages, setMessages] = React.useState(initialMessages);
  const [inputText, setInputText] = React.useState('');
  const [isTyping, setIsTyping] = React.useState(false);

  /* ---------- Handlers ---------- */
  const handleSend = () => {
    if (!inputText.trim()) return;
    const newMessage = {
      id: messages.length + 1,
      role: 'user',
      name: 'You',
      timestamp: 'Just now',
      text: inputText,
    };
    setMessages([...messages, newMessage]);
    setInputText('');
    // Simulate assistant typing
    setIsTyping(true);
    setTimeout(() => {
      const reply = {
        id: messages.length + 2,
        role: 'assistant',
        name: 'ChatBot',
        timestamp: 'Just now',
        text: 'Thanks for your message! How else can I assist you?',
      };
      setMessages(prev => [...prev, reply]);
      setIsTyping(false);
    }, 2000);
  };

  /* ---------- Render ---------- */
  return (
    <div className="h-screen flex flex-col font-inter text-slate-900">
      {/* Header */}
      <div className="bg-slate-900">
        <div className="px-8 py-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center text-white text-2xl font-bold">
                CJ
              </div>
              <div>
                <h1 className="text-2xl font-bold text-white">ChatOps</h1>
                <p className="text-slate-300 text-sm mt-1">AI‑powered conversation hub</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <Button className="bg-slate-700 text-white border border-slate-600 hover:bg-slate-600">
                Search
              </Button>
              <Button className="bg-blue-600 text-white hover:bg-blue-700">
                New Chat
              </Button>
              <div className="ml-3 flex items-center gap-2">
                <button className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center text-white hover:bg-slate-600">
                  •
                </button>
                <div className="w-10 h-10 rounded-full bg-orange-500 flex items-center justify-center text-white font-bold border-2 border-white">
                  JH
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Main layout */}
      <div className="flex flex-1 overflow-hidden bg-slate-100">
        {/* Sidebar */}
        <aside className="w-64 bg-white border-r border-slate-200 flex flex-col">
          <div className="p-4 font-semibold text-slate-700">Conversations</div>
          <div className="flex-1 overflow-y-auto">
            {conversations.map((c) => (
              <div key={c.id} className="flex items-center px-4 py-3 hover:bg-slate-50 cursor-pointer">
                <Avatar className="mr-3">
                  <AvatarFallback>{c.name.slice(0, 2)}</AvatarFallback>
                </Avatar>
                <div>
                  <div className="text-sm font-medium text-slate-900">{c.name}</div>
                  <div className="text-xs text-slate-500">{c.timestamp}</div>
                </div>
              </div>
            ))}
          </div>
        </aside>

        {/* Chat area */}
        <main className="flex-1 flex flex-col">
          {/* Chat messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {messages.map((m) => (
              <ChatBubble
                key={m.id}
                role={m.role}
                name={m.name}
                timestamp={m.timestamp}
                className={m.role === 'user' ? 'ml-auto' : ''}
              >
                {m.text}
              </ChatBubble>
            ))}
            {isTyping && (
              <div className="flex items-center space-x-2 mt-2">
                <StreamingIndicator variant="dots" color="#A772F2" size="sm" />
                <span className="text-sm text-slate-600">ChatBot is typing…</span>
              </div>
            )}
          </div>

          {/* Message input */}
          <div className="p-4 border-t border-slate-200 bg-white">
            <div className="flex items-center space-x-2">
              <Input
                className="flex-1 rounded-xl border-slate-300 focus:border-blue-600 focus:ring-0"
                placeholder="Type your message..."
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              />
              <Button
                onClick={handleSend}
                className="bg-blue-600 hover:bg-blue-700 text-white rounded-xl px-4 py-2"
              >
                Send
              </Button>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

